57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
64	     * domain containing at least one dot, with no whitespace in any part.
65	     */
66	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        validateRequiredFields(ownerFieldsDto);
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
118	        rejectDuplicateTelephone(telephone);
119	        owner.setTelephone(telephone);
120	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
121	        if (owner.getRegistrationDate() == null) {
122	            owner.setRegistrationDate(LocalDate.now());
123	        }
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
134	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
135	        if (currentOwner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        currentOwner.setAddress(ownerFieldsDto.getAddress());
139	        currentOwner.setCity(ownerFieldsDto.getCity());
140	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
141	        currentOwner.setLastName(ownerFieldsDto.getLastName());
142	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
143	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
