225	    /**
226	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
227	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
228	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
229	     *
230	     * @param ownerFieldsDto the submitted owner fields
231	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
232	     *                                     name of every offending field
233	     */
234	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
235	        List<String> missingFields = new ArrayList<>();
236	        if (isBlank(ownerFieldsDto.getFirstName())) {
237	            missingFields.add("firstName");
238	        }
239	        if (isBlank(ownerFieldsDto.getLastName())) {
240	            missingFields.add("lastName");
241	        }
242	        if (isBlank(ownerFieldsDto.getAddress())) {
243	            missingFields.add("address");
244	        }
245	        if (isBlank(ownerFieldsDto.getCity())) {
246	            missingFields.add("city");
247	        }
248	        if (isBlank(ownerFieldsDto.getTelephone())) {
249	            missingFields.add("telephone");
250	        }
251	        if (!missingFields.isEmpty()) {
252	            throw new InvalidOwnerFieldsException(missingFields);
253	        }
254	    }
255	
256	    private boolean isBlank(String value) {
257	        return value == null || value.isBlank();
258	    }
259	
260	    /**
261	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
262	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
263	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
264	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
265	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
266	     *
267	     * @param telephone the raw telephone value submitted by the client
268	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
269	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
270	     *                                     400 response
271	     */
272	    private String normalizeTelephone(String telephone) {
273	        String e164 = toE164(telephone);
274	        if (e164 == null) {
275	            throw new InvalidOwnerFieldsException(List.of("telephone"));
276	        }
277	        return e164;
278	    }
279	
280	    /**
281	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
282	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
283	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
284	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
285	     *
286	     * @param telephone the raw telephone value, possibly {@code null}
287	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
288	     */
289	    private String toE164(String telephone) {
290	        if (telephone == null) {
291	            return null;
292	        }
293	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
294	        boolean hasPlus = cleaned.startsWith("+");
295	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
296	        String nationalSignificant = hasPlus
297	            ? digits
298	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
299	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
300	            return null;
301	        }
302	        return "+" + nationalSignificant;
303	    }
304	
305	    /**
306	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
307	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
308	     * returned value is that address lower-cased.
309	     *
310	     * @param email the raw email value submitted by the client, or {@code null} if omitted
311	     * @return the lower-cased email, or {@code null} if none was supplied
312	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
313	     *                                     yielding a 400 response
314	     */
315	    private String normalizeEmail(String email) {
316	        if (email == null) {
317	            return null;
318	        }
319	        if (!EMAIL_PATTERN.matcher(email).matches()) {
320	            throw new InvalidOwnerFieldsException(List.of("email"));
321	        }
322	        return email.toLowerCase(Locale.ROOT);
323	    }
324	
325	    /**
326	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
327	     * telephones are converted to E.164 here as well so the comparison is independent of the format
328	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
329	     * ignored rather than matched.
330	     *
331	     * @param telephone the E.164 telephone of the owner being created
332	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
333	     *                                          yielding a 409 Conflict response
334	     */
335	    private void rejectDuplicateTelephone(String telephone) {
336	        boolean inUse = this.clinicService.findAllOwners().stream()
337	            .map(Owner::getTelephone)
338	            .map(this::toE164)
339	            .anyMatch(telephone::equals);
340	        if (inUse) {
341	            throw new DuplicateOwnerTelephoneException(telephone);
342	        }
343	    }
344	}
